-- ==============================================================================
-- V1__baseline.sql — schéma fourni pour la flotte de véhicules
--
-- Reproduit les 11 tables et les 10 vues du schéma PostgreSQL de référence :
-- colonnes, clés primaires en GENERATED BY DEFAULT AS IDENTITY, clés étrangères,
-- contraintes UNIQUE et CHECK nommées. Les corps des vues ne sont pas fournis
-- par le schéma source : ils sont reconstruits de façon cohérente avec leurs
-- colonnes et avec les besoins de F12, F15, F16, F17 et F18.
--
-- V1 est un baseline Flyway : NE JAMAIS MODIFIER CETTE MIGRATION.
-- ==============================================================================

-- ══════════════════════════════════════════════════════════════════════════════
--  TABLES
-- ══════════════════════════════════════════════════════════════════════════════

CREATE TABLE site (
    id_site integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT site_pkey PRIMARY KEY,
    nom character varying NOT NULL,
    adresse character varying NOT NULL
);

CREATE TABLE salarie (
    id_salarie integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT salarie_pkey PRIMARY KEY,
    nom character varying NOT NULL,
    prenom character varying NOT NULL,
    email character varying NOT NULL CONSTRAINT salarie_email_key UNIQUE
);

CREATE TABLE prestataire (
    id_prestataire integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT prestataire_pkey PRIMARY KEY,
    nom character varying NOT NULL,
    adresse character varying,
    telephone character varying
);

CREATE TABLE type_entretien (
    id_type_entretien integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT type_entretien_pkey PRIMARY KEY,
    libelle character varying NOT NULL CONSTRAINT type_entretien_libelle_key UNIQUE,
    periodicite_km integer NOT NULL CONSTRAINT type_entretien_periodicite_km_check CHECK ((periodicite_km > 0)),
    periodicite_mois integer NOT NULL CONSTRAINT type_entretien_periodicite_mois_check CHECK ((periodicite_mois > 0)),
    categorie character varying
);

CREATE TABLE type_depense (
    id_type_depense integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT type_depense_pkey PRIMARY KEY,
    libelle character varying NOT NULL CONSTRAINT type_depense_libelle_key UNIQUE,
    avec_conducteur boolean NOT NULL DEFAULT false
);

CREATE TABLE vehicule (
    id_vehicule integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT vehicule_pkey PRIMARY KEY,
    immatriculation character varying NOT NULL CONSTRAINT vehicule_immatriculation_key UNIQUE,
    marque character varying NOT NULL,
    modele character varying NOT NULL,
    date_mise_en_service date NOT NULL,
    mode_acquisition character varying NOT NULL,
    partage boolean NOT NULL DEFAULT false,
    prix_achat numeric,
    date_sortie date,
    id_site integer NOT NULL CONSTRAINT vehicule_id_site_fkey REFERENCES site(id_site),
    id_vehicule_remplace integer CONSTRAINT vehicule_id_vehicule_remplace_fkey REFERENCES vehicule(id_vehicule),
    CONSTRAINT uq_vehicule_remplace UNIQUE (id_vehicule_remplace),
    CONSTRAINT ck_vehicule_pas_son_remplacement CHECK (((id_vehicule_remplace IS NULL) OR (id_vehicule_remplace <> id_vehicule))),
    CONSTRAINT ck_vehicule_sortie CHECK (((date_sortie IS NULL) OR (date_sortie >= date_mise_en_service))),
    CONSTRAINT ck_vehicule_prix_achat CHECK (((prix_achat IS NULL) OR ((mode_acquisition)::text = 'PROPRIETE'::text))),
    CONSTRAINT vehicule_mode_acquisition_check CHECK (((mode_acquisition)::text = ANY ((ARRAY['PROPRIETE'::character varying, 'LOCATION_LONGUE_DUREE'::character varying, 'LEASING'::character varying])::text[]))),
    CONSTRAINT vehicule_prix_achat_check CHECK ((prix_achat >= (0)::numeric))
);

CREATE TABLE affectation (
    id_affectation integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT affectation_pkey PRIMARY KEY,
    date_debut date NOT NULL,
    date_fin date,
    id_vehicule integer NOT NULL CONSTRAINT affectation_id_vehicule_fkey REFERENCES vehicule(id_vehicule),
    id_salarie integer NOT NULL CONSTRAINT affectation_id_salarie_fkey REFERENCES salarie(id_salarie),
    CONSTRAINT ck_affectation_dates CHECK (((date_fin IS NULL) OR (date_fin >= date_debut)))
);

CREATE TABLE entretien (
    id_entretien integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT entretien_pkey PRIMARY KEY,
    date_debut date NOT NULL,
    date_fin date,
    cout numeric NOT NULL,
    km_compteur integer NOT NULL,
    id_vehicule integer NOT NULL CONSTRAINT entretien_id_vehicule_fkey REFERENCES vehicule(id_vehicule),
    id_type_entretien integer NOT NULL CONSTRAINT entretien_id_type_entretien_fkey REFERENCES type_entretien(id_type_entretien),
    id_prestataire integer NOT NULL CONSTRAINT entretien_id_prestataire_fkey REFERENCES prestataire(id_prestataire),
    CONSTRAINT ck_entretien_dates CHECK (((date_fin IS NULL) OR (date_fin >= date_debut))),
    CONSTRAINT entretien_cout_check CHECK ((cout >= (0)::numeric)),
    CONSTRAINT entretien_km_compteur_check CHECK ((km_compteur >= 0))
);

CREATE TABLE contrat (
    id_contrat integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT contrat_pkey PRIMARY KEY,
    date_debut date NOT NULL,
    duree_mois integer NOT NULL,
    loyer_mensuel numeric NOT NULL,
    km_autorise integer NOT NULL,
    id_vehicule integer NOT NULL CONSTRAINT contrat_id_vehicule_fkey REFERENCES vehicule(id_vehicule),
    CONSTRAINT uq_contrat_vehicule UNIQUE (id_vehicule),
    CONSTRAINT contrat_duree_mois_check CHECK ((duree_mois > 0)),
    CONSTRAINT contrat_loyer_mensuel_check CHECK ((loyer_mensuel > (0)::numeric)),
    CONSTRAINT contrat_km_autorise_check CHECK ((km_autorise > 0))
);

CREATE TABLE depense (
    id_depense integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT depense_pkey PRIMARY KEY,
    date_depense date NOT NULL,
    montant numeric NOT NULL,
    commentaire character varying,
    id_vehicule integer NOT NULL CONSTRAINT depense_id_vehicule_fkey REFERENCES vehicule(id_vehicule),
    id_type_depense integer NOT NULL CONSTRAINT depense_id_type_depense_fkey REFERENCES type_depense(id_type_depense),
    CONSTRAINT depense_montant_check CHECK ((montant > (0)::numeric))
);

CREATE TABLE trajet (
    id_trajet integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT trajet_pkey PRIMARY KEY,
    date_trajet date NOT NULL,
    km_depart integer NOT NULL,
    km_arrivee integer NOT NULL,
    motif character varying,
    id_affectation integer NOT NULL CONSTRAINT trajet_id_affectation_fkey REFERENCES affectation(id_affectation),
    CONSTRAINT ck_trajet_compteur CHECK ((km_arrivee >= km_depart)),
    CONSTRAINT trajet_km_depart_check CHECK ((km_depart >= 0))
);

-- ══════════════════════════════════════════════════════════════════════════════
--  VUES (lecture seule, jamais mappées comme entités JPA)
-- ══════════════════════════════════════════════════════════════════════════════

-- F12 : recouvrement entre une affectation et une immobilisation.
CREATE VIEW v_conflit_affectation_entretien AS
SELECT a.id_affectation, e.id_entretien, a.id_vehicule
FROM affectation a
JOIN entretien e ON e.id_vehicule = a.id_vehicule
WHERE (e.date_fin IS NULL OR a.date_debut <= e.date_fin)
  AND (a.date_fin IS NULL OR e.date_debut <= a.date_fin);

-- F15, F16, F17 : échéance kilométrique et temporelle par type périodique.
-- Sans entretien périodique, la mise en service sert de point de départ.
CREATE VIEW v_echeance_entretien AS
SELECT v.id_vehicule,
       t.id_type_entretien,
       t.libelle,
       COALESCE(d.date_dernier, v.date_mise_en_service) AS date_dernier,
       COALESCE(d.km_dernier, 0) AS km_dernier,
       COALESCE(d.km_dernier, 0) + t.periodicite_km AS km_prochain,
       (COALESCE(d.date_dernier, v.date_mise_en_service)
           + (t.periodicite_mois || ' months')::interval)::date AS date_prochaine,
       GREATEST(COALESCE(k.km_entretien, 0), COALESCE(ktr.km_trajet, 0)) AS km_actuel,
       (GREATEST(COALESCE(k.km_entretien, 0), COALESCE(ktr.km_trajet, 0))
            >= COALESCE(d.km_dernier, 0) + t.periodicite_km
        OR CURRENT_DATE > (COALESCE(d.date_dernier, v.date_mise_en_service)
            + (t.periodicite_mois || ' months')::interval)::date) AS en_retard
FROM vehicule v
CROSS JOIN type_entretien t
LEFT JOIN (
    SELECT id_vehicule, id_type_entretien,
           MAX(date_debut) AS date_dernier, MAX(km_compteur) AS km_dernier
    FROM entretien
    GROUP BY id_vehicule, id_type_entretien
) d ON d.id_vehicule = v.id_vehicule AND d.id_type_entretien = t.id_type_entretien
LEFT JOIN (
    SELECT id_vehicule, MAX(km_compteur) AS km_entretien
    FROM entretien GROUP BY id_vehicule
) k ON k.id_vehicule = v.id_vehicule
LEFT JOIN (
    SELECT a.id_vehicule, MAX(tr.km_arrivee) AS km_trajet
    FROM trajet tr JOIN affectation a ON a.id_affectation = tr.id_affectation
    GROUP BY a.id_vehicule
) ktr ON ktr.id_vehicule = v.id_vehicule
WHERE t.categorie = 'PERIODIQUE';

-- F18 : coût d'entretien, âge et compteur ; cout_au_km est protégé contre la division par zéro.
CREATE VIEW v_bilan_vehicule AS
SELECT v.id_vehicule,
       v.immatriculation,
       COALESCE(c.cout_total, 0) AS cout_total,
       DATE_PART('year', AGE(CURRENT_DATE, v.date_mise_en_service))::integer AS age_annees,
       GREATEST(COALESCE(k.km_entretien, 0), COALESCE(ktr.km_trajet, 0)) AS km_compteur_actuel,
       CASE WHEN GREATEST(COALESCE(k.km_entretien, 0), COALESCE(ktr.km_trajet, 0)) = 0 THEN 0
            ELSE ROUND(COALESCE(c.cout_total, 0)
                 / GREATEST(COALESCE(k.km_entretien, 0), COALESCE(ktr.km_trajet, 0)), 2)
       END AS cout_au_km
FROM vehicule v
LEFT JOIN (
    SELECT id_vehicule, SUM(cout) AS cout_total FROM entretien GROUP BY id_vehicule
) c ON c.id_vehicule = v.id_vehicule
LEFT JOIN (
    SELECT id_vehicule, MAX(km_compteur) AS km_entretien FROM entretien GROUP BY id_vehicule
) k ON k.id_vehicule = v.id_vehicule
LEFT JOIN (
    SELECT a.id_vehicule, MAX(tr.km_arrivee) AS km_trajet
    FROM trajet tr JOIN affectation a ON a.id_affectation = tr.id_affectation
    GROUP BY a.id_vehicule
) ktr ON ktr.id_vehicule = v.id_vehicule;

-- F18 : ventilation achat / contrats / entretiens / dépenses.
-- D-03 : seul cout_entretiens est utilisé pour le coût demandé par F18.
CREATE VIEW v_cout_total_vehicule AS
SELECT v.id_vehicule,
       v.immatriculation,
       COALESCE(v.prix_achat, 0) AS cout_achat,
       COALESCE((SELECT SUM(c.duree_mois * c.loyer_mensuel)
                 FROM contrat c WHERE c.id_vehicule = v.id_vehicule), 0) AS cout_contrats,
       COALESCE((SELECT SUM(e.cout) FROM entretien e
                 WHERE e.id_vehicule = v.id_vehicule), 0) AS cout_entretiens,
       COALESCE((SELECT SUM(d.montant) FROM depense d
                 WHERE d.id_vehicule = v.id_vehicule), 0) AS cout_depenses,
       COALESCE(v.prix_achat, 0)
         + COALESCE((SELECT SUM(c.duree_mois * c.loyer_mensuel)
                     FROM contrat c WHERE c.id_vehicule = v.id_vehicule), 0)
         + COALESCE((SELECT SUM(e.cout) FROM entretien e
                     WHERE e.id_vehicule = v.id_vehicule), 0)
         + COALESCE((SELECT SUM(d.montant) FROM depense d
                     WHERE d.id_vehicule = v.id_vehicule), 0) AS cout_total
FROM vehicule v;

CREATE VIEW v_depense_conducteur AS
SELECT d.id_depense, d.id_vehicule, d.date_depense, a.id_salarie
FROM depense d
JOIN type_depense td ON td.id_type_depense = d.id_type_depense AND td.avec_conducteur
JOIN affectation a ON a.id_vehicule = d.id_vehicule
                  AND a.date_debut <= d.date_depense
                  AND (a.date_fin IS NULL OR d.date_depense <= a.date_fin);

CREATE VIEW v_depense_sans_conducteur AS
SELECT d.id_depense, d.id_vehicule, d.date_depense
FROM depense d
WHERE NOT EXISTS (
    SELECT 1 FROM affectation a
    WHERE a.id_vehicule = d.id_vehicule
      AND a.date_debut <= d.date_depense
      AND (a.date_fin IS NULL OR d.date_depense <= a.date_fin)
);

CREATE VIEW v_remplacement_incoherent AS
SELECT n.id_vehicule AS id_nouveau, n.id_vehicule_remplace AS id_ancien
FROM vehicule n
JOIN vehicule a ON a.id_vehicule = n.id_vehicule_remplace
WHERE a.date_mise_en_service > n.date_mise_en_service;

CREATE VIEW v_trajet_hors_affectation AS
SELECT t.id_trajet, t.date_trajet, t.id_affectation
FROM trajet t
JOIN affectation a ON a.id_affectation = t.id_affectation
WHERE t.date_trajet < a.date_debut
   OR (a.date_fin IS NOT NULL AND t.date_trajet > a.date_fin);

CREATE VIEW v_trajet_incoherent AS
SELECT t.id_trajet, a.id_vehicule, t.date_trajet,
       t.km_depart, t.km_arrivee, p.km_arrivee_precedent
FROM trajet t
JOIN affectation a ON a.id_affectation = t.id_affectation
JOIN LATERAL (
    SELECT MAX(t2.km_arrivee) AS km_arrivee_precedent
    FROM trajet t2
    WHERE t2.id_affectation = t.id_affectation
      AND (t2.date_trajet, t2.id_trajet) < (t.date_trajet, t.id_trajet)
) p ON true
WHERE t.km_depart < p.km_arrivee_precedent;

CREATE VIEW v_vehicule_sans_contrat AS
SELECT v.id_vehicule, v.immatriculation, v.mode_acquisition
FROM vehicule v
WHERE v.mode_acquisition <> 'PROPRIETE'
  AND NOT EXISTS (SELECT 1 FROM contrat c WHERE c.id_vehicule = v.id_vehicule);
